function kcal(value){if(typeof value!=='string'||!/^\d+(?:\.\d)?$/.test(value))return '—';const [whole,fraction]=value.split('.');return whole.replace(/\B(?=(\d{3})+(?!\d))/g,',')+(fraction===undefined?'':'.'+fraction);}
function calories(raw){if(raw===null||raw===undefined||(typeof raw==='string'&&!raw.trim()))return null;if(typeof raw!=='string'||raw.length>128||!/^\d+(?:\.\d)?$/.test(raw.trim()))throw new Error('热量需为0至20,000 kcal的数值，最多1位小数；未知请留空。');const parts=raw.trim().split('.');const value=BigInt(parts[0]+(parts[1]||'').padEnd(1,'0'));if(value>200000n)throw new Error('这份食物总热量不能超过20,000 kcal。');const digits=value.toString().padStart(2,'0');return digits.slice(0,-1)+'.'+digits.slice(-1);}
function macroValue(raw,key){if(raw===null||raw===undefined||(typeof raw==='string'&&!raw.trim()))return null;if(typeof raw!=='string'||raw.length>128||/[\u0000-\u001f\u007f]/.test(raw)||!/^\d+(?:\.\d)?$/.test(raw.trim()))throw new Error(macroNames[key]+'需为0至20,000g的数值，最多1位小数；未知请留空。');const parts=raw.trim().split('.'),tenth=BigInt(parts[0]+(parts[1]||'').padEnd(1,'0'));if(tenth>200000n)throw new Error(macroNames[key]+'不能超过20,000g。');return (Number(tenth)/10).toFixed(1);}
