function text(raw,label,max,required=false){if(typeof raw!=='string')throw new Error('请填写'+label+'。');const value=raw.trim();const invalid=label==='备注'?/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/:/[\u0000-\u001f\u007f]/;if((required&&!value)||value.length>max||invalid.test(value))throw new Error(label+'需'+(required?'填写且':'')+'不超过'+max+'个字符，不能包含不支持的控制字符。');return value;}
function path(){const params=new URLSearchParams({date:state.date});if(state.includeDeleted)params.set('includeDeleted','1');return '/health/nutrition?'+params;}
