function storedBody(body){if(!body||!validDay(body.date)||!Object.hasOwn(meals,body.meal))throw new Error('原提交信息无效，请先核对记录。');const normalized={date:body.date,meal:body.meal,name:text(body.name,'食物名称',100,true),portion:text(body.portion,'份量',100),calories:calories(body.calories),note:text(body.note,'备注',500)};for(const key of macroKeys)if(Object.hasOwn(body,key))normalized[key]=macroValue(body[key],key);if(body.food){if(typeof body.food.id!=='string'||body.food.id.length>120||!Number.isFinite(body.food.amount)||body.food.amount<=0||typeof body.food.unit!=='string'||body.food.unit.length>20)throw new Error('原食物库份量信息无效。');if(Object.hasOwn(body.food,'catalogRelease')&&(typeof body.food.catalogRelease!=='string'||!body.food.catalogRelease||body.food.catalogRelease.length>100))throw new Error('原食物库版本信息无效。');normalized.food={id:body.food.id,amount:body.food.amount,unit:body.food.unit,...foodRelease(body.food)};}if(Object.hasOwn(body,'provenance'))normalized.provenance=p1CleanProvenance(body.provenance);return normalized;}
function readPending(){const raw=nutritionStorage.getItem(pendingKey);if(!raw)return null;const operation=JSON.parse(raw);if(!uuid.test(operation?.key))throw new Error('上次新增的确认信息暂时无法读取，请先核对记录。');return {key:operation.key,body:storedBody(operation.body)};}
function readBatchPending(){const raw=nutritionStorage.getItem(batchKey);if(!raw)return null;const operation=JSON.parse(raw);if(!uuid.test(operation?.key)||!Array.isArray(operation?.body?.entries)||!operation.body.entries.length||operation.body.entries.length>30)throw new Error('上次批量新增的确认信息暂时无法读取，请先核对记录。');return {key:operation.key,body:{entries:operation.body.entries.map(storedBody)}};}
