function summaryLabel(summary){if(!summary.entryCount)return '暂无记录';if(!summary.knownCount)return '热量未填';return '已填 '+kcal(summary.knownCalories)+' kcal'+(summary.unknownCount?' · '+summary.unknownCount+'项未填':'');}
function renderSummaryBase(){const summary=state.data.summary,active=state.data.entries.filter((entry)=>!entry.deleted),total=summary.knownCount?kcal(summary.knownCalories)+'<small>kcal</small>':'—';const cards=[{key:'total',label:'已记录热量',value:total,note:!summary.entryCount?'还没有食物记录':summary.unknownCount?summary.unknownCount+' 项热量待补充':'共 '+summary.entryCount+' 项食物'}];for(const key of macroKeys){const known=active.filter((entry)=>typeof entry[key]==='string'&&/^\d+(?:\.\d)?$/.test(entry[key]));const tenth=known.reduce((sum,entry)=>{const [whole,fraction='0']=entry[key].split('.');return sum+BigInt(whole+fraction);},0n),digits=tenth.toString().padStart(2,'0'),missing=active.length-known.length;cards.push({key,label:macroNames[key],value:known.length?kcal(digits.slice(0,-1)+'.'+digits.slice(-1))+'<small>g</small>':'—',note:!active.length?'按已记录食物统计':missing?missing+' 项待补充':'已填写的合计'});}el('summary').innerHTML=cards.map((card)=>'<article class="nt-card"><h2>'+card.label+'</h2><div class="nt-number'+(card.value==='—'?' empty':'')+'" id="nutrition-'+(card.key==='total'?'total':'summary-'+card.key)+'">'+card.value+'</div><p>'+card.note+'</p></article>').join('')+'<span class="nt-summary-meta" id="nutrition-count">'+summary.entryCount+' 项食物</span><span class="nt-summary-meta" id="nutrition-unknown">'+summary.unknownCount+' 项热量待补充</span>';}
function renderWeek(){const data=state.data;el('week-range').textContent=data.recentFrom+' — '+data.recentTo;el('week').innerHTML=data.recent7days.map((day)=>{const label=day.date+'，'+summaryLabel(day.summary)+'，'+day.summary.entryCount+'项食物';return '<button class="nt-week-day" type="button" data-nutrition-date="'+day.date+'" aria-label="'+esc(label)+'" aria-pressed="'+String(day.date===state.date)+'"'+(!validDay(day.date)||day.date>state.today?' disabled':'')+'><span>'+day.date.slice(5)+'</span><strong>'+(!day.summary.entryCount?'暂无记录':day.summary.knownCount?kcal(day.summary.knownCalories)+' kcal':'热量未填')+'</strong><span>'+day.summary.entryCount+' 项'+(day.summary.unknownCount?' · '+day.summary.unknownCount+'项未填':'')+'</span></button>';}).join('');}
function sourceText(food){return food?.source?food.source.name+' · '+food.source.version+(food.catalogRelease?' · 目录 '+food.catalogRelease:' · 原始目录')+(food.estimated?' · 份量估算':''):'';}
