async function load(){const sequence=++state.sequence;state.controller?.abort();const controller=new AbortController();state.controller=controller;const date=state.date;el('page').setAttribute('aria-busy','true');el('content').hidden=true;controls();status('正在读取'+date+'的饮食记录…');try{const params=new URLSearchParams({date});if(state.includeDeleted)params.set('includeDeleted','1');const data=await request('/api/health/nutrition?'+params,{signal:controller.signal});if(sequence!==state.sequence)return false;if(data.date!==date||!Array.isArray(data.entries)||!data.summary||!Array.isArray(data.recent7days))throw new Error('饮食记录暂时无法读取，请重试。');state.data=data;state.today=validDay(data.today)?data.today:today();render();status('');loadFavorites();state.reviewLoadedKey=null;if(el('history')?.open)loadReview();return true;}catch(error){if(sequence!==state.sequence||error?.name==='AbortError')return false;status(error?.message||'饮食记录读取失败。',true,error?.status===401||error?.code==='SIGN_IN_REQUIRED');return false;}finally{if(sequence===state.sequence){state.controller=null;el('page').setAttribute('aria-busy','false');}}}
