function fieldsBase(){const date=el('form-day').value;if(!validDay(date)||date>today()){focusField('form-day');throw new Error('请选择有效且不晚于今天的日期。');}const meal=el('meal').value;if(!Object.hasOwn(meals,meal)){focusField('meal');throw new Error('请选择早餐、午餐、晚餐或加餐。');}let name,portion,note,amount;try{name=text(el('name').value,'食物名称',100,true);}catch(error){focusField('name');throw error;}try{portion=text(el('portion').value,'份量',100);}catch(error){focusField('portion');throw error;}try{amount=calories(el('calories').value);}catch(error){focusField('calories');throw error;}try{note=text(el('note').value,'备注',500);}catch(error){focusField('note');throw error;}const result={date,meal,name,portion,calories:amount,note};for(const key of macroKeys){try{result[key]=macroValue(el(key).value,key);}catch(error){focusField(key);throw error;}}if(state.form?.food){const quantity=Number(el('food-quantity').value),unit=el('food-unit').value;const preview=foodAmount(state.form.food,quantity,unit);result.food={id:state.form.food.id,amount:quantity,unit,...foodRelease(state.form.food)};result.name=state.form.food.name;result.portion=foodPortion(state.form.food,quantity,unit);result.calories=preview.calories;}else if(state.form?.entry?.food)result.food=null;return result;}
