const foodCache=new Map();
function foodKey(food){const id=food?.foodId||food?.id||'';return food?.catalogRelease?food.catalogRelease+'|'+id:id;}
function foodRelease(food){return typeof food?.catalogRelease==='string'?{catalogRelease:food.catalogRelease}:{};}
function servingFood(food){return food?.basis==='perServing';}
