function foodEnergyLabel(food){return servingFood(food)?'每份 '+food.serving.kcal+' kcal（'+food.serving.label+'）':'每100g '+food.kcalPer100g+' kcal';}
function foodDefault(food){return servingFood(food)?{amount:1,unit:'份'}:{amount:100,unit:'g'};}
function foodPortion(food,amount,unit){return servingFood(food)?amount+' 份（'+food.serving.label+'）':amount+' '+unit;}
function foodPreview(food,result,amount,unit){return servingFood(food)?'当前 '+foodPortion(food,amount,unit)+'，合计 '+result.calories+' kcal。官方未提供可靠克重，不按重量换算':'当前份量 '+Number(result.grams.toFixed(2))+'g，合计 '+result.calories+' kcal'+(result.estimated?'（份量估算）':'');}
