function unitOptions(food,selected){return unitChoices(food).map((item)=>'<option value="'+esc(item.unit)+'"'+(item.unit===selected?' selected':'')+'>'+esc(item.label||item.unit+(item.unit!=='g'&&item.unit!=='kg'?'（'+item.grams+'g）':''))+'</option>').join('');}
function foodTenth(amount,weight,density,basis=100){let numerator=10n,denominator=BigInt(basis);for(const value of [amount,weight,density]){const digits=String(value);if(!/^\d+(?:\.\d+)?$/.test(digits))throw new Error('份量或营养数值格式不正确。');const [whole,decimal='']=digits.split('.');numerator*=BigInt(whole+decimal);denominator*=10n**BigInt(decimal.length);}return Number((numerator*2n+denominator)/(denominator*2n));}
