function setFormFoodBase(food,amount,unit){if(!state.form)return;state.form.food=food;el('food-selection').hidden=!food;if(food){const defaults=foodDefault(food);amount=amount??defaults.amount;unit=unit??defaults.unit;foodCache.set(foodKey(food),food);el('food-title').textContent=food.name+(food.state?' · '+food.state:'');el('food-source').textContent=sourceText(food)+' · '+foodEnergyLabel(food);el('food-unit').innerHTML=unitOptions(food,unit);el('food-unit').value=unitChoices(food).some((item)=>item.unit===unit)?unit:defaults.unit;el('food-quantity').value=String(amount);el('name').value=food.name;updateFormCalculation();}else el('food-preview').textContent='';formControls();}
function updateFormCalculationBase(){if(!state.form?.food)return;try{const food=state.form.food,amount=Number(el('food-quantity').value),unit=el('food-unit').value,result=foodAmount(food,amount,unit);el('portion').value=foodPortion(food,amount,unit);el('calories').value=result.calories;for(const key of macroKeys)el(key).value=result[key]??'';el('food-preview').textContent=foodPreview(food,result,amount,unit)+'。保存时会由服务器按食物库核算。';}catch(error){el('calories').value='';for(const key of macroKeys)el(key).value='';el('food-preview').textContent=error.message;}}
