function catalogNotice(source){if(Array.isArray(source))return source.map(catalogNotice).join('');if(!source||typeof source.description!=='string')return '';const link=(url,label)=>typeof url==='string'&&/^https:\/\//.test(url)?'<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">'+label+'</a>':'';return '<li class="nt-source nt-catalog-notice"><details><summary>食物库来源与版本'+(source.name?' · '+esc(source.name):'')+(source.version?' · '+esc(source.version):'')+'</summary><p>'+esc(source.description)+'</p><p>'+esc(source.attribution||'')+'</p>'+(source.rightsNotice?'<p>'+esc(source.rightsNotice)+'</p>':'')+'<p>'+link(source.url,'官方资料')+' '+link(source.licenseUrl,'开放授权条款')+'</p></details></li>';}
async function searchFormFoods(){if(state.busy||frozen()||!state.form)return;const q=el('food-search').value.trim();if(!q){el('food-results').textContent='输入食物名称或别名，再点搜索。';return;}const sequence=++state.foodSequence,formSequence=state.formSequence;el('food-results').textContent='正在搜索食物库…';try{const data=await request('/api/health/nutrition/foods?'+new URLSearchParams({q}));if(sequence!==state.foodSequence||formSequence!==state.formSequence||!dialog.open)return;state.foodResults=Array.isArray(data.foods)?data.foods:[];cacheFoods(state.foodResults);el('food-results').innerHTML=(state.foodResults.length?state.foodResults.map((food)=>'<li><button class="nt-food-choice" type="button" data-food-id="'+esc(foodKey(food))+'" title="'+esc(food.name+' · '+foodEnergyLabel(food))+'"><span class="nt-food-choice-info"><strong>'+esc(food.name)+'</strong><span class="nt-food-choice-meta">'+esc(servingFood(food)?food.category||food.state||'':food.state||food.category||'')+'</span></span><span class="nt-food-choice-energy">'+esc(servingFood(food)?'每份 '+food.serving.kcal+' kcal':'每100g '+food.kcalPer100g+' kcal')+'</span></button></li>').join(''):'没有找到匹配食物。品牌产品请按实际包装标签填写；未知热量和营养素留空。')+catalogNotice(data.sources??data.source);}catch(error){if(sequence===state.foodSequence&&formSequence===state.formSequence)el('food-results').textContent=error.message;}}
